# Expand authored explanations with independently computed numerical examples at build time.
for key,ch in chapters.items():
    if int(key)==6: continue
    sections=[]
    for i,lab in enumerate(ch['labs']):
        title,paragraph=ch['teachingNotes'][min(i,len(ch['teachingNotes'])-1)].split('~',1)
        if i>=len(ch['teachingNotes']): title=lab['title']
        lab['question']='ก่อนเปลี่ยนค่าหนึ่งตัว ให้ทำนายว่า output และค่าระหว่างทางใดควรเปลี่ยน แล้วคงตัวอื่นเพื่อทดสอบเหตุผลของคุณ'
        sections.append({'slug':f'mechanism-{i+1}','title':f'{i+1}. {title}','lab':lab['id'],'why':paragraph,
          'intuition':f'ใช้การทดลอง “{lab["title"]}” เพื่อดูกรณีเล็กก่อนขยายไป implementation เต็ม อ่าน input และหน่วยของ controls ให้ตรงกับ output โดยตรึง baseline แล้วเปลี่ยนเพียงปัจจัยที่ต้องการทดสอบ',
          'symbols':'__COMPUTED_SYMBOLS__','derivation':['__COMPUTED_DERIVATION__'],
          'experiment':'คืนค่าเริ่มต้นและบันทึก baseline → ทำนายทิศ/ขนาดผลต่าง → เปลี่ยน control หนึ่งตัว → ตรวจ intermediate table → อธิบายด้วยสมการ → รัน Python/tests เทียบ',
          'failure':paragraph.split(' ต้อง')[-1] if ' ต้อง' in paragraph else 'ตรวจ input, shape, หน่วยและสมมติฐานของตัวอย่าง ก่อนย้ายข้อสรุปจากข้อมูลเล็กไปยังข้อมูลจริง'})
    ch['sections']=sections
assert set(map(int,chapters))==set(range(1,81))
for ch in chapters.values():
    ids=[l['id'] for l in ch['labs']]
    if len(set(ids))!=len(ids): raise ValueError(('duplicate lab id',ch['id'],ids))
path.write_text(json.dumps(dict(sorted(chapters.items(),key=lambda kv:int(kv[0]))),ensure_ascii=False,indent=2)+'\n')
print('Authored teaching briefs and experiment presets: 80 chapters')
